"""Byte-preserving historical self-check resource; no production-route revival."""

import hashlib
import os
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
import zipfile

from harness_foundry_factory.compiler import _write_portable_self_check

ROOT = Path(__file__).resolve().parents[1]
# Generated by compiler.py at 3542301, before extraction. Deliberately independent
# of the resource under test so a changed oracle cannot silently bless itself.
LEGACY_SHA256 = "3dc8cb6c3e1ba92f66d79fa43f8aad924a6846e6c6973165da5d130435b15811"


class PortableSelfCheckResourceTests(unittest.TestCase):
    def test_emitted_script_matches_pre_extraction_bytes_and_parses(self):
        with tempfile.TemporaryDirectory() as temporary:
            root = Path(temporary)
            _write_portable_self_check(root)
            script = root / "tools/self_check.py"
            content = script.read_bytes()
            self.assertEqual(hashlib.sha256(content).hexdigest(), LEGACY_SHA256)
            self.assertEqual(content, (ROOT / "src/harness_foundry_factory/resources/portable_self_check.py.in").read_bytes())
            compile(content, str(script), "exec")

    def test_relocated_source_archive_loads_its_own_resource(self):
        with tempfile.TemporaryDirectory(prefix="foundry resource ") as temporary:
            root = Path(temporary)
            archive = root / "source.zip"
            with zipfile.ZipFile(archive, "w") as bundle:
                for source in sorted((ROOT / "src").rglob("*")):
                    if not source.is_file() or not (source.suffix == ".py" or source.name == "portable_self_check.py.in"):
                        continue
                    bundle.write(source, source.relative_to(ROOT))
            relocated = root / "isolated 汉"
            with zipfile.ZipFile(archive) as bundle:
                bundle.extractall(relocated)
            output = root / "output"
            code = """
import pathlib, sys
source = pathlib.Path(sys.argv[1])
sys.path.insert(0, str(source / 'src'))
from harness_foundry_factory import compiler
assert pathlib.Path(compiler.__file__).resolve().is_relative_to(source.resolve())
compiler._write_portable_self_check(pathlib.Path(sys.argv[2]))
"""
            result = subprocess.run([sys.executable, "-I", "-B", "-c", code,
                                     str(relocated), str(output)], cwd=root,
                                    env={k: v for k, v in os.environ.items() if k != "PYTHONPATH"},
                                    capture_output=True, text=True, timeout=30)
            self.assertEqual(result.returncode, 0, result.stdout + result.stderr)
            self.assertEqual(hashlib.sha256((output / "tools/self_check.py").read_bytes()).hexdigest(), LEGACY_SHA256)

    def test_legacy_distribution_carries_template_without_host_dependency_claim(self):
        from harness_foundry_factory.portable import package_local
        result = package_local(None)
        self.assertEqual(result["status"], "PREFLIGHT_PASS")
        self.assertIn("src/harness_foundry_factory/resources/portable_self_check.py.in", result["manifest"]["files"])
        self.assertNotIn("harness_foundry_runtime", result["manifest"]["dependency_discovery"]["external_imports"])
